def solve(text):
    if not text or not text.strip():
        return None

    # Remove whitespace
    text = text.strip()

    # Check for valid suffix
    suffix = ''
    i = len(text) - 1
    while i >= 0 and text[i].isdigit():
        i -= 1
    if i < 0:
        return None  # Only digits, no suffix

    # Extract suffix
    suffix_start = i + 1
    if suffix_start >= len(text):
        return None

    suffix = text[suffix_start:]

    # Validate suffix
    valid_suffixes = {'ms': 1, 's': 1000, 'm': 60000, 'h': 3600000}
    if suffix not in valid_suffixes:
        return None

    # Extract the number part
    num_str = text[:suffix_start]

    # Validate number part
    if not num_str or not all(c.isdigit() or c == '.' for c in num_str):
        return None

    # Check for fractional part
    if '.' in num_str:
        return None  # Fractional milliseconds not allowed

